    var how = (x) => { var tr = trOf(x.transit), k = transitKind(x.transit); return k === 'car' ? 'รถยนต์' : k === 'walk' ? 'เดิน' : `${tr.label}${x.station ? ' · ' + x.station : ''}${x.exit ? ' ทางออก ' + x.exit : ''}`; };
